private lemma clInput_backward (x w : List Bool) : ∀ j (hj : j ≤ x.length),
    clInputTM.tm.runFrom (clInputCfg x 1 ⟨j, by omega⟩ w ((j : ℤ) - 1)) (j + 1) =
      clInputCfg x 2 1 w 0

private theorem recordStep_orbit_one_step {K : ℕ} {Γ S : Type} {x : List Γ}
    (M : MultiTapeTM K Γ S) (c : Cfg K Γ S x) (r : ℕ) :
    roundOrbit M (fun _ => 1) c (r + 1) = M.step (roundOrbit M (fun _ => 1) c r)

private theorem iw_one {k : ℕ} {S : Type} {z : List Bool} (M : MultiTapeTM k Bool S)
    (c : Cfg k Bool S z) (q : S) (hc : c.state = some q) :
    M.runFrom c 1 = (M.tr q c.inputSymbol c.workTapeSymbols).apply c

private lemma emCall_track_initial (M : FinTM Bool) (x : List Bool) :
    (emCallTrackTM M).tm.runFrom ((emCallTrackTM M).tm.initCfg x) 1 =
      emCallTrackCfg M (M.tm.initCfg x) (fun _ => 0) (fun _ => 0)

private lemma splitEmit_separator (k : ℕ) (w s : List Bool) (out : List Bool) :
    (splitEmitTM k).tm.runFrom (splitEmitCfg k w s (some 0) s.length s.length out) 2 =
      splitEmitCfg k w s (some 3) s.length s.length (out ++ [false, true])

private lemma emitterToken_separator (x out : List Bool) (i : ℕ) (hi : i ≤ x.length) :
    unaryTokenTM.tm.runFrom (scanCfg x (some (3 : Fin 6)) i hi out) 2 =
      scanCfg x (some (5 : Fin 6)) i hi (out ++ [false, true])

private lemma fl_leaf_run {k : ℕ} {x : List Bool} (d : Cfg (k + 2) Bool (Option Bool) x)
    (live : Bool) (hd : d.state = some (some live)) :
    (fl_leafTM k).runFrom d 1 = fl_flush (if live then some none else none) d

private lemma zr_mir_lockstep {k : ℕ} {S : Type} {x : List (ZoneSym k)}
    (M : MultiTapeTM 2 (ZoneSym k) S) (X : Set (Option S)) :
    Lockstep (x := x) (x' := x) M (zr_mirTM M) zr_mir (fun _ => 1) X X

private lemma canonTag_step {m : ℕ} {x : List Bool}
    (d : Cfg m Bool (Option (Option Bool)) x) (hs : d.state = some none) :
    (canonTagTM m).runFrom d 1 =
      { d with
        state := some (some d.inputSymbol)
        inputPos := moveInputPos d.inputPos (if d.inputSymbol.isSome then 1 else 0) }

private lemma canonTrueOrbit {k : ℕ} {x : List Bool}
    (d : Cfg k Bool (Option Bool) x) (hs : d.state = some (some true))
    (p r : ℕ) (hp : d.inputPos.val = p + 1) (hr : p + r ≤ x.length)
    (hprefix : ∀ i < r, x[p + i]? = some true) :
    counterLoopOrbit (canonCellTM k true) (fun _ => 1) d r =
      { d with state := some (some true), inputPos := ⟨p + r + 1, by omega⟩ }

